expand_details.cypher:
MATCH (start:node {name: 'k8s-master'})
CALL apoc.path.expandConfig(start, {
    sequence: 'node,hosts,pod,contains,container,manages,TCP socket',
    minLevel: 0,
    maxLevel: 3,
    bfs: true
})
YIELD path
RETURN path, length(path) AS hops
ORDER BY hops;

